/**
 * EblanEng Worker - Dedicated Background Worker for Terrain Gen & Greedy Meshing
 */

const WASM_BASE64 = '';
let wasmInstance = null;
let exports = null;
let wasmMemory = null;
let isReady = false;

let dataBaseUrl = self.location?.href;
async function initWasm(seed) {
    try {
        let wasmBytes = null;
        try {
            const resp = await fetch(new URL('js/eblan_core.wasm', dataBaseUrl).href);
            if (resp.ok) wasmBytes = await resp.arrayBuffer();
        } catch (e) {}

        if (!wasmBytes) {
            const bin = atob(WASM_BASE64);
            const bytes = new Uint8Array(bin.length);
            for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
            wasmBytes = bytes.buffer;
        }

        const res = await WebAssembly.instantiate(wasmBytes, {});
        wasmInstance = res.instance;
        exports = res.instance.exports;
        wasmMemory = exports.memory;
        exports.eblan_init(seed || 1337);
        isReady = true;
        self.postMessage({ type: 'READY' });
    } catch (err) {
        self.postMessage({ type: 'ERROR', error: err.message });
    }
}

async function handleMessage(e) {
    const data = e.data;
    if (!data) return;

    if (data.type === 'INIT') {
        dataBaseUrl = data.baseUrl || dataBaseUrl;
        await initWasm(data.seed);
        if (data.blockMaterials && exports) {
            for (let item of data.blockMaterials) {
                exports.eblan_set_block_material(item.block, item.face, item.matId);
            }
        }
        return;
    }

    if (data.type === 'SYNC_MATERIALS') {
        if (isReady && data.blockMaterials) {
            for (let item of data.blockMaterials) {
                exports.eblan_set_block_material(item.block, item.face, item.matId);
            }
        }
        return;
    }

    if (data.type === 'SET_SEED') {
        if (exports && exports.eblan_set_seed) {
            exports.eblan_set_seed(data.seed);
        }
        return;
    }

    if (data.type === 'GEN_AND_MESH') {
        if (!isReady) {
            self.postMessage({ type: 'CHUNK_FAILED', id: data.id, error: 'Wasm not ready' });
            return;
        }

        let mem = wasmMemory.buffer;
        const cx = data.cx;
        const cz = data.cz;

        // 1. Generate chunk or copy existing voxels
        const voxelsPtr = exports.eblan_get_chunk_voxels_ptr();
        if (data.voxels) {
            new Uint8Array(mem, voxelsPtr, 8192).set(data.voxels);
        } else {
            exports.eblan_set_seed(data.seed);
            exports.eblan_generate_chunk(cx, cz, data.dimension ?? 0, data.worldType ?? 0, data.waterLevel ?? 6);
            mem = wasmMemory.buffer;
        }

        // Copy generated voxels out for world storage
        const chunkVoxels = new Uint8Array(8192);
        chunkVoxels.set(new Uint8Array(mem, voxelsPtr, 8192));

        if (data.generateOnly) {
            self.postMessage({ type: 'CHUNK_READY', id: data.id, voxels: chunkVoxels }, [chunkVoxels.buffer]);
            return;
        }

        // 2. Set neighbors if available
        const dirs = [
            { dir: 0, voxels: data.rightVoxels },
            { dir: 1, voxels: data.leftVoxels },
            { dir: 4, voxels: data.frontVoxels },
            { dir: 5, voxels: data.backVoxels }
        ];

        for (let d of dirs) {
            if (d.voxels && d.voxels.length === 8192) {
                const nPtr = exports.eblan_get_neighbor_voxels_ptr(d.dir);
                new Uint8Array(mem, nPtr, 8192).set(d.voxels);
            } else {
                exports.eblan_set_neighbor_present(d.dir, 0);
            }
        }

        // 3. Mesh Chunk
        const vertexCount = exports.eblan_mesh_chunk(cx, cz);
        mem = wasmMemory.buffer;
        if (vertexCount === 0) {
            self.postMessage({
                type: 'CHUNK_READY',
                id: data.id,
                cx: cx,
                cz: cz,
                positions: new Float32Array(0),
                normals: new Float32Array(0),
                uvs: new Float32Array(0),
                groups: new Uint32Array(0),
                voxels: chunkVoxels
            }, [chunkVoxels.buffer]);
            return;
        }

        const posPtr = exports.eblan_get_positions_ptr();
        const normPtr = exports.eblan_get_normals_ptr();
        const uvPtr = exports.eblan_get_uvs_ptr();
        const grpPtr = exports.eblan_get_groups_ptr();
        const grpCount = exports.eblan_get_group_count();

        // Direct allocations to transfer ownership
        const positions = new Float32Array(vertexCount * 3);
        positions.set(new Float32Array(mem, posPtr, vertexCount * 3));

        const normals = new Float32Array(vertexCount * 3);
        normals.set(new Float32Array(mem, normPtr, vertexCount * 3));

        const uvs = new Float32Array(vertexCount * 2);
        uvs.set(new Float32Array(mem, uvPtr, vertexCount * 2));

        const groups = new Uint32Array(grpCount * 3);
        groups.set(new Uint32Array(mem, grpPtr, grpCount * 3));

        // Transfer with zero-copy Transferable Objects!
        self.postMessage({
            type: 'CHUNK_READY',
            id: data.id,
            cx: cx,
            cz: cz,
            positions: positions,
            normals: normals,
            uvs: uvs,
            groups: groups,
            voxels: chunkVoxels
        }, [positions.buffer, normals.buffer, uvs.buffer, groups.buffer, chunkVoxels.buffer]);
    }
};

self.onmessage = async e => {
    try { await handleMessage(e); }
    catch (error) { self.postMessage({ type: 'CHUNK_FAILED', id: e.data?.id, error: error.message }); }
};
